Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN=202;
const int INF=0x3f3f3f3f;

int flow[MAXN][MAXN], capacity[MAXN][MAXN], parent[MAXN], dist[MAXN];
int gridA[11][11], gridB[11][11], n, t, bi, bj;
int matrix[101][101];
vector<int> listA, listB, listC;
int directions[4][2]={{0,1},{0,-1},{1,0},{-1,0}};

int edmonds_karp(int n, int s, int e) {
    int total=0;
    while (true) {
        memset(parent, -1, sizeof(parent));
        dist[s]=INF;
        int front=0, rear=0;
        queue<int> q;
        q.push(s);
        while (!q.empty() && parent[e]<0) {
            int u=q.front(); q.pop();
            for (int v=0; v<n; v++) {
                if (parent[v]<0 && capacity[u][v]-flow[u][v]>0) {
                    parent[v]=u;
                    dist[v]=min(dist[u], capacity[u][v]-flow[u][v]);
                    q.push(v);
                }
            }
        }
        if (parent[e]<0) break;
        for (int v=e; v!=s; v=parent[v]) {
            flow[parent[v]][v]+=dist[e];
            flow[v][parent[v]]-=dist[e];
        }
        total+=dist[e];
    }
    return total;
}

void explore(int A, int B, int* visited, bool check) {
    queue<pair<int,int>> q;
    visited[A*n+B]=0;
    q.push({A,B});
    while (!q.empty()) {
        auto p=q.front(); q.pop();
        int pIdx=p.first*n+p.second;
        int dis=visited[pIdx];
        if (check && (matrix[bi*n+bj][pIdx]<=dis || t<=dis)) {
            if (matrix[bi*n+bj][pIdx]<dis || t<dis) visited[pIdx]=INF+1;
            continue;
        }
        for (int d=0; d<4; d++) {
            int ni=p.first+directions[d][0];
            int nj=p.second+directions[d][1];
            if (ni<0 || nj<0 || ni>=n || nj>=n) continue;
            if (gridB[ni][nj]<'0' || gridB[ni][nj]>'9') continue;
            int qIdx=ni*n+nj;
            if (visited[qIdx]!=INF) continue;
            visited[qIdx]=dis+1;
            q.push({ni,nj});
        }
    }
}

int main() {
    cin>>n>>t;
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) cin>>gridA[i][j];
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) cin>>gridB[i][j];
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]=='Z') bi=i, bj=j;
        }
    }
    memset(matrix, 0x3f, sizeof(matrix));
    explore(bi, bj, matrix[bi*n+bj], false);
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]>='1' && gridA[i][j]<='9') {
                explore(i, j, matrix[i*n+j], true);
            }
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridA[i][j]>='0' && gridA[i][j]<='9') {
                int p=i*n+j;
                capacity[p+2+ n*n][1]=gridA[i][j]-'0';
            }
        }
    }
    int z=bi*n+bj;
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gridB[i][j]>='0' && gridB[i][j]<='9') {
                int p=i*n+j;
                capacity[0][p+2]=gridB[i][j]-'0';
                for (int k=0; k<(int)listA.size(); k++) {
                    int ii=listA[k], jj=listB[k], qIdx=ii*n+jj;
                    if (matrix[p][qIdx]<INF)
                        capacity[p+2][qIdx+2+ n*n]=INF;
                }
            }
        }
    }
    cout<<edmonds_karp(2+n*n, 0, 1)<<endl;
}
