import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 202;
    static final int INF = 0x3f3f3f3f;
    static int[][] flow = new int[MAXN][MAXN];
    static int[][] capacity = new int[MAXN][MAXN];
    static int[] parent = new int[MAXN];
    static int[] dist = new int[MAXN];
    static int[][] gridA = new int[11][11];
    static int[][] gridB = new int[11][11];
    static int n, t, bi, bj;
    static int[][] matrix = new int[101][101];
    static List<Integer> listA = new ArrayList<>();
    static List<Integer> listB = new ArrayList<>();
    static List<Integer> listC = new ArrayList<>();
    static int[][] directions = {{0,1},{0,-1},{1,0},{-1,0}};
    static final int INF_VAL = INF + 1;

    public static int edmonds_karp(int n, int s, int e) {
        int total = 0;
        while (true) {
            Arrays.fill(parent, -1);
            Arrays.fill(dist, 0);
            dist[s] = INF;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty() && parent[e] < 0) {
                int u = q.poll();
                for (int v = 0; v < n; v++) {
                    if (parent[v] < 0 && capacity[u][v] - flow[u][v] > 0) {
                        parent[v] = u;
                        dist[v] = Math.min(dist[u], capacity[u][v] - flow[u][v]);
                        q.offer(v);
                    }
                }
            }
            if (parent[e] < 0) break;
            for (int v = e; v != s; v = parent[v]) {
                flow[parent[v]][v] += dist[e];
                flow[v][parent[v]] -= dist[e];
            }
            total += dist[e];
        }
        return total;
